mapper.select:
SELECT COUNT(*)
FROM tbl_reservation
WHERE bno      = #{bno}
  AND res_date = #{resDate}
  AND status IN ('RESERVED', 'USING')
  AND (
        #{startTime} < end_time
    AND #{endTime}   > start_time
  )

mapper.update:
UPDATE tbl_reservation
SET status = 'CANCELLED'
WHERE res_id = #{resId}
  AND userid = #{userid}
  AND status = 'RESERVED'
